function mpSpecGuess(it, ev) { const act = it.wcl && it.wcl.actors; if (!act || !act.get || typeof E === 'undefined' || !E.SPECS) return; const ros = new Set((it.roster || []).map(mpLc)), casts = new Map();
  for (const e of ev) { if (e.type !== 'cast') continue; const a = act.get(e.sourceID); if (!a || a.type !== 'Player') continue; const m = casts.get(e.sourceID) || new Map(); m.set(e.abilityGameID, (m.get(e.abilityGameID) || 0) + 1); casts.set(e.sourceID, m); }
  const t0 = ev.length ? ev[0].timestamp : 0, add = [];
  for (const [id, m] of casts) { const a = act.get(id), cls = String(a.subType || '').toUpperCase(); if (ros.size && !ros.has(mpLc(a.name))) continue; let best = 0, bs = 0;
    for (const [sid, sc] of Object.entries(E.SPECS)) { if (sc[1] !== cls) continue; const T = MP_SPECS[sc[0] + ' ' + ((E.CLASSES[sc[1]] || [])[0] || '')]; if (!T) continue; const ids = new Set(T.r.flatMap((r) => (r[3] || []).concat(r[4] || [])).map(Number)); let n = 0; for (const [ab, c] of m) if (ids.has(+ab)) n += c; if (n > bs) { bs = n; best = +sid; } }
    if (best) add.push({ timestamp: t0, type: 'combatantinfo', sourceID: id, specID: best, gear: [], auras: [], talentTree: [] }); }
  ev.unshift(...add); }
