    try { R.skips = mpSkipBuild(mpSkipRaw(text, E), R); } catch (e) { console.error(e); R.skips = []; } /* (pack skips, Nov 3) */
    MP.R[k] = R; if (!MPC_ON) R._txtGet = it.wcl ? (() => Promise.resolve(text)) : () => (it.getText ? it.getText() : it.shr ? shrText(it) : FH.dir ? fhText(it.startByte, it.endByte) : S.file.slice(it.startByte, it.endByte).text()); /* (the website's Rotation tab reads a picked pull again (Nov 5)) */
    if (MP_ROT_ON && !MP_RK_OLD) { if (MP.item && mpK(MP.item) === k) setTimeout(() => mpRwStart(R, text), 250); else R._rwOff = true; } /* (a fast run's key isn't checked) */
