    const f1 = (v) => (Math.round(v * 10) / 10).toFixed(1).replace(/\.0$/, '') + '%', fr = F && F.route && F.route.ok && F.route.full === rt.full ? F.route : null;
    const lo = !!fr && rt.total / rt.full < fr.total / fr.full - 0.0005;
