  // amber when you took more, green when fewer; a placeholder while the fast run loads)
  const d = nY - nF, hd = F ? (d > 0 ? 'You took <b class="a">' + plural(d, 'more pull') + '</b> than the fast run' : d < 0 ? 'You took <b class="g">' + plural(-d, 'fewer pull') + '</b> than the fast run' : '<b>The same number of pulls</b> as the fast run')
    : wait ? mpShimT('You took 3 more pulls than the fast run') : '';
