const mpBand = (R, fx, right, pre) => { if (!MPC_ON) right = ''; return '<div class="mpt-band' + (right ? '' : ' mpt-band1') + '" id="mptBand">' + (pre || '') + '<div class="mpt-bl">' + mpPartHtml(R, fx, MP.pp) + '</div>' + (right ? '<div class="mpt-br">' + right + '</div>' : '') + '</div>'; };
