  for (const b of (p.ebuffs || []).filter((x) => x.on > 0).slice(0, 2)) t(esc(b.spell) + ' ×' + b.on, '', '<b>' + esc(b.spell) + '</b> went on ' + en(b.on) + '.' + (b.removed ? ' ' + b.removed + ' purged (' + who(p.purges, b.spell) + ').' : ''));
